const state={role:null,user:null,students:[],rooms:[],complaints:[],leaves:[],movements:[],visitors:[],payments:[],menu:[],notices:[],feedback:[],stats:{},page:'overview',dark:false,stream:null,refreshing:false};
const $=s=>document.querySelector(s); const $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const initials=n=>String(n||'Resident').split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase();
const fmtDate=v=>v?new Date(v).toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'}):'—';
const fmtTime=v=>v?new Date(v).toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'}):'—';
const toast=(msg,type='ok')=>{const d=document.createElement('div');d.className=`toast ${type}`;d.textContent=msg;$('#toastStack').appendChild(d);setTimeout(()=>d.remove(),3000)};
async function api(url,opts={}){const r=await fetch(url,{headers:{'Content-Type':'application/json',...(opts.headers||{})},...opts});if(!r.ok){let m='Request failed';try{const x=await r.json();m=x.message||x.error||m}catch{}throw new Error(m)}return r.status===204?null:r.json()}
async function loadAll(){const [students,rooms,complaints,leaves,movements,visitors,payments,menu,notices,feedback,stats]=await Promise.all([api('/api/students'),api('/api/rooms'),api('/api/complaints'),api('/api/leaves'),api('/api/movements'),api('/api/visitors'),api('/api/payments'),api('/api/mess'),api('/api/notices'),api('/api/feedback'),api('/api/dashboard')]);Object.assign(state,{students,rooms,complaints,leaves,movements,visitors,payments,menu,notices,feedback,stats});}
function setUser(u){state.user=u;localStorage.setItem('hostelhubUser',JSON.stringify(u))}
function currentStudent(){return state.students.find(s=>s.registerNumber===state.user?.registerNumber)||state.students.find(s=>s.name===state.user?.displayName)}
function showApp(){ $('#loginView').classList.add('hidden');$('#app').classList.remove('hidden'); updateIdentity(); buildNav(); renderPage(); startRealtime(); }
function updateIdentity(){const u=state.user||{};const name=u.displayName||'Resident';$('#sideAvatar').textContent=initials(name);$('#sideName').textContent=name;$('#sideReg').textContent=u.registerNumber||'ADMIN';$('#miniAvatar').textContent=initials(name);$('#miniName').textContent=name;$('#miniRole').textContent=u.role==='ADMIN'?'Warden / Admin':'Student';$('#portalLabel').textContent=u.role==='ADMIN'?'WARDEN CONSOLE':'STUDENT PORTAL'}
function buildNav(){const admin=state.role==='ADMIN';const groups=admin?[['WORKSPACE',[['overview','▦','Dashboard'],['students','♙','Students'],['rooms','⌂','Rooms'],['movement','↔','Gate movement'],['complaints','!','Complaints'],['leaves','◷','Leave approvals']]],['OPERATIONS',[['fees','₹','Fees & payments'],['mess','✦','Mess menu'],['visitors','◎','Visitors'],['notices','▤','Notices & events'],['feedback','♡','Feedback']]],['ACCOUNT',[['settings','⚙','Settings']]]]:[['MY HOSTEL',[['overview','⌂','Home'],['profile','◎','My profile'],['passport','↔','Hostel passport'],['mess','✦','Mess & meals'],['events','▣','Events & notices'],['requests','△','Complaints & leave'],['feedback','♡','Feedback']]],['ACCOUNT',[['settings','⚙','Settings']]]];
$('#sideNav').innerHTML=groups.map(g=>`<div class="nav-section">${g[0]}</div>${g[1].map(x=>`<button class="nav-item ${state.page===x[0]?'active':''}" data-page="${x[0]}"><span class="ico">${x[1]}</span>${x[2]}${countFor(x[0])?`<span class="count">${countFor(x[0])}</span>`:''}</button>`).join('')}`).join('');$$('.nav-item').forEach(b=>b.onclick=()=>{state.page=b.dataset.page;$('#sidebar').classList.remove('open');$('#mobileBackdrop').classList.remove('show');buildNav();renderPage()});}
function countFor(p){if(p==='complaints')return state.complaints.filter(x=>x.status==='OPEN').length||'';if(p==='movement')return state.movements.filter(x=>x.status==='REQUESTED').length||'';if(p==='leaves')return state.leaves.filter(x=>x.status==='PENDING').length||'';if(p==='feedback')return state.feedback.length||'';return ''}
function renderPage(){const pages={overview:state.role==='ADMIN'?renderAdminDashboard:renderStudentHome,students:renderStudents,rooms:renderRooms,movement:renderMovements,complaints:renderComplaints,leaves:renderLeaves,fees:renderFees,mess:renderMess,visitors:renderVisitors,notices:renderNotices,feedback:renderFeedback,profile:renderProfile,passport:renderPassport,events:renderStudentEvents,requests:renderStudentRequests,settings:renderSettings};(pages[state.page]||pages.overview)();$('#pageTitle').textContent=document.querySelector('.page-heading h1')?.textContent||titleMap[state.page]||'Overview'}
const titleMap={overview:'Overview',students:'Students',rooms:'Rooms',movement:'Gate movement',complaints:'Complaints',leaves:'Leave approvals',fees:'Fees & payments',mess:'Mess menu',visitors:'Visitors',notices:'Notices & events',feedback:'Feedback',profile:'My profile',passport:'Hostel passport',events:'Events & notices',requests:'Complaints & leave',settings:'Settings'};
function pageHead(kicker,title,sub,actions=''){return `<div class="page-heading"><div><span class="eyebrow">${kicker}</span><h1>${title}</h1><p>${sub}</p></div><div class="toolbar">${actions}</div></div>`}
function stat(label,value,sub,icon,cls=''){return `<div class="stat ${cls}"><div class="stat-top"><span>${label}</span><span class="stat-icon">${icon}</span></div><b>${value}</b><small>${sub}</small></div>`}
function renderAdminDashboard(){const s=state.stats;$('#pageRoot').innerHTML=pageHead('WARDEN CONSOLE','Good evening, Warden','A live view of hostel operations, resident safety and approvals.')+`<section class="hero"><div class="hero-grid"><div><span class="eyebrow">TCE LADIES HOSTEL · LIVE OPERATIONS</span><h1>Everything under control.</h1><p>Monitor occupancy, resident movement, complaints, leave requests and daily hostel operations from one workspace.</p><div class="hero-actions"><button class="btn primary" onclick="go('movement')">Review gate requests →</button><button class="btn ghost" onclick="go('complaints')">Open complaints</button></div></div><div class="hero-orbit"><div><b>${s.occupancyPercent||0}%</b><small>occupancy</small></div></div></div></section><div class="stats">${stat('RESIDENTS',s.students||0,'Registered residents','♙')}${stat('OCCUPANCY',`${s.occupied||0}/${s.capacity||0}`,'Beds occupied','⌂')}${stat('OPEN COMPLAINTS',s.openComplaints||0,'Need attention','!')}${stat('OUTSIDE NOW',s.studentsOut||0,'Gate movement','↔')}</div><div class="grid-2"><div class="card"><div class="card-head"><h3>Priority attention</h3><span>Needs action now</span></div>${adminComplaintRows(state.complaints.filter(x=>x.status!=='RESOLVED').slice(0,5))}</div><div class="card"><div class="card-head"><h3>Today's gate desk</h3><span>${s.pendingExitRequests||0} pending</span></div>${movementRows(state.movements.filter(x=>x.status==='REQUESTED').slice(0,4),true)}</div></div><div class="grid-2" style="margin-top:16px"><div class="card"><div class="card-head"><h3>Recent activity</h3><span>Live workspace</span></div><div class="timeline">${recentActivity().map(x=>`<div class="timeline-item"><i></i><div><b>${esc(x.text)}</b><small>${x.time}</small></div></div>`).join('')||'<div class="empty">No recent activity yet.</div>'}</div></div><div class="card"><div class="card-head"><h3>Hostel snapshot</h3><span>Today</span></div><div class="info-grid"><div class="info-box"><span>VISITORS INSIDE</span><b>${s.visitorsInside||0}</b></div><div class="info-box"><span>PENDING LEAVE</span><b>${s.pendingLeaves||0}</b></div><div class="info-box"><span>PENDING FEES</span><b>${s.pendingFees||0}</b></div><div class="info-box"><span>ROOMS</span><b>${s.rooms||0}</b></div></div></div></div>`}
function adminComplaintRows(a){if(!a.length)return '<div class="empty">All complaints are cleared.</div>';return `<div class="table-wrap"><table class="data-table"><thead><tr><th>RESIDENT</th><th>ISSUE</th><th>PRIORITY</th><th>STATUS</th><th></th></tr></thead><tbody>${a.map(c=>`<tr><td><div class="student-cell"><div class="mini-avatar">${initials(c.studentName)}</div><span>${esc(c.studentName)}</span></div></td><td>${esc(c.category)}</td><td><span class="pill ${c.priority==='HIGH'?'red':c.priority==='MEDIUM'?'orange':'blue'}">${c.priority}</span></td><td><span class="pill ${statusClass(c.status)}">${c.status}</span></td><td><button class="action success" onclick="approveComplaint(${c.id})">${c.status==='OPEN'?'Approve':'Resolve'}</button></td></tr>`).join('')}</tbody></table></div>`}
function renderStudentHome(){const st=currentStudent()||{};const s=state.stats;const m=state.movements.find(x=>x.registerNumber===st.registerNumber&&x.status==='OUT');const last=state.movements.find(x=>x.registerNumber===st.registerNumber);$('#pageRoot').innerHTML=`<section class="hero"><div class="hero-grid"><div><span class="eyebrow">TCE LADIES HOSTEL · STUDENT SPACE</span><h1>Hi, ${esc((st.name||'Resident').split(' ')[0])}. Your hostel, in one place.</h1><p>Stay updated on your room, meals, events, fees and gate movement without chasing the office.</p><div class="hero-actions"><button class="btn primary" onclick="go('passport')">Manage gate pass →</button><button class="btn ghost" onclick="openModal('complaint')">Report an issue</button></div></div><div class="hero-orbit"><div><b>${m?'OUT':'IN'}</b><small>gate status</small></div></div></div></section><div class="stats">${stat('MY ROOM',st.roomNumber||'—',st.roomNumber?'Allocated room':'Contact warden','⌂')}${stat('FEE STATUS',st.feeStatus||'PENDING',st.feeStatus==='PAID'?'Account clear':'Payment required','₹')}${stat('GATE STATUS',m?'OUT':'IN','Live movement status',m?'↗':'✓')}${stat('SUPPORT','9–5','Hostel office','✦')}</div><div class="grid-2"><div class="card"><div class="card-head"><h3>Latest announcements</h3><button class="action" onclick="go('events')">View all</button></div>${state.notices.slice(-4).reverse().map(n=>noticeHtml(n)).join('')||'<div class="empty">No announcements.</div>'}</div><div class="card"><div class="card-head"><h3>Quick actions</h3><span>Resident services</span></div><div class="request-cards"><button class="request-card" onclick="openModal('movement')"><span class="req-icon">↔</span><b>Go out</b><small>Request warden approval before leaving.</small></button><button class="request-card" onclick="openModal('leave')"><span class="req-icon">◷</span><b>Apply leave</b><small>Submit home or personal leave dates.</small></button><button class="request-card" onclick="openModal('complaint')"><span class="req-icon">!</span><b>Raise complaint</b><small>Maintenance, Wi-Fi, mess or other issues.</small></button></div></div></div><div class="card" style="margin-top:16px"><div class="card-head"><h3>Today's mess</h3><button class="action" onclick="go('mess')">See weekly menu</button></div><div class="menu-grid">${todayMeals().map(x=>`<div class="meal"><div class="meal-icon">${x.icon}</div><b>${x.label}</b><small>${esc(x.value||'Not updated')}</small></div>`).join('')}</div></div><div class="grid-2" style="margin-top:16px"><div class="card"><div class="card-head"><h3>My recent movement</h3><button class="action" onclick="go('passport')">Passport</button></div>${last?movementCard(last):'<div class="empty">No gate movement recorded.</div>'}</div><div class="card"><div class="card-head"><h3>Hostel facilities</h3><span>Resident amenities</span></div><div class="info-grid"><div class="info-box"><span>WI-FI</span><b>Available</b></div><div class="info-box"><span>CCTV</span><b>24 × 7</b></div><div class="info-box"><span>STUDY ROOM</span><b>Open</b></div><div class="info-box"><span>HOSTEL OFFICE</span><b>9 AM – 5 PM</b></div></div></div></div>`}
function todayMeals(){const day=new Date().toLocaleDateString('en-US',{weekday:'long'});const m=state.menu.find(x=>x.dayOfWeek===day)||state.menu[0]||{};return [{label:'Breakfast',value:m.breakfast,icon:'☕'},{label:'Lunch',value:m.lunch,icon:'◒'},{label:'Snacks',value:m.snacks,icon:'✦'},{label:'Dinner',value:m.dinner,icon:'◔'}]}
function renderProfile(){const s=currentStudent()||{};$('#pageRoot').innerHTML=pageHead('MY ACCOUNT','My profile','Your resident identity, room and hostel account details.')+`<div class="profile-layout"><div class="profile-hero"><div class="profile-large">${initials(s.name)}</div><h2>${esc(s.name||'Resident')}</h2><p>${esc(s.department||'Department')} · ${esc(s.year||'Year')} Year<br>Thiagarajar College of Engineering</p><div class="profile-badges"><span>ACTIVE RESIDENT</span><span>${esc(s.registerNumber||'—')}</span><span>${s.feeStatus==='PAID'?'FEES CLEAR':'FEE DUE'}</span></div></div><div class="card"><div class="card-head"><h3>Resident information</h3><button class="action" onclick="openModal('profile')">Edit details</button></div><div class="info-grid"><div class="info-box"><span>REGISTER NUMBER</span><b>${esc(s.registerNumber)}</b></div><div class="info-box"><span>EMAIL</span><b>${esc(s.email)}</b></div><div class="info-box"><span>DEPARTMENT</span><b>${esc(s.department)}</b></div><div class="info-box"><span>YEAR</span><b>${esc(s.year)} Year</b></div><div class="info-box"><span>ROOM</span><b>${esc(s.roomNumber||'Not allocated')}</b></div><div class="info-box"><span>BLOCK</span><b>${esc(state.rooms.find(r=>r.roomNumber===s.roomNumber)?.blockName||'—')}</b></div></div></div></div>`}
function renderPassport(){const s=currentStudent()||{};const mine=state.movements.filter(x=>x.registerNumber===s.registerNumber);const active=mine.find(x=>x.status==='OUT');$('#pageRoot').innerHTML=pageHead('HOSTEL PASSPORT','Gate & movement','Request permission, track approvals and confirm your return.')+`<div class="hero" style="min-height:180px"><div class="hero-grid"><div><span class="eyebrow">LIVE RESIDENCY STATUS</span><h1>${active?'You are currently outside.':'You are inside the hostel.'}</h1><p>${active?'Please complete check-in when you return to campus.':'Need to go out? Submit a request and wait for the warden approval.'}</p><div class="hero-actions"><button class="btn primary" onclick="${active?`checkInMine(${active.id})`:`openModal('movement')`} ">${active?'Mark my return':'Request to go out'} →</button></div></div><div class="hero-orbit"><div><b>${active?'OUT':'IN'}</b><small>current status</small></div></div></div></div><div class="grid-2" style="margin-top:16px"><div class="card"><div class="card-head"><h3>My requests</h3><span>Latest first</span></div>${mine.slice(0,6).map(movementCard).join('')||'<div class="empty">No requests yet.</div>'}</div><div class="card"><div class="card-head"><h3>Gate rules</h3></div><div class="timeline"><div class="timeline-item"><i></i><div><b>Request before leaving</b><small>Wait for the warden to approve your movement.</small></div></div><div class="timeline-item"><i></i><div><b>Carry your hostel ID</b><small>Keep your resident identity available at the gate.</small></div></div><div class="timeline-item"><i></i><div><b>Check back in</b><small>Use the return action when you enter the hostel again.</small></div></div></div></div></div>`}
function renderStudentEvents(){const ev=state.notices.filter(n=>(n.audience||'').toLowerCase().includes('event')||/event|holiday|festival/i.test(n.title));const all=ev.length?ev:state.notices;$('#pageRoot').innerHTML=pageHead('HOSTEL LIFE','Events & notices','Stay current with hostel announcements, activities and important dates.')+`<div class="grid-2"><div class="card"><div class="card-head"><h3>Upcoming events</h3><span>Campus & hostel</span></div>${all.map(noticeHtml).join('')||'<div class="empty">No events published yet.</div>'}</div><div class="card"><div class="card-head"><h3>Hostel highlights</h3></div><div class="hero" style="min-height:300px;padding:22px"><div><span class="eyebrow">COMMUNITY</span><h1 style="font-size:25px">A better stay starts with better information.</h1><p>From meals and events to gate movement and support, HostelHub keeps everyday resident life organised.</p></div></div></div></div>`}
function renderStudentRequests(){const s=currentStudent()||{};const cs=state.complaints.filter(x=>x.studentName===s.name).slice().reverse();const ls=state.leaves.filter(x=>x.registerNumber===s.registerNumber).slice().reverse();$('#pageRoot').innerHTML=pageHead('RESIDENT SERVICES','Complaints & leave','Raise issues, request leave and follow every approval.')+`<div class="request-cards"><button class="request-card" onclick="openModal('complaint')"><span class="req-icon">!</span><b>New complaint</b><small>Report a maintenance, internet, electrical, mess or safety issue.</small></button><button class="request-card" onclick="openModal('leave')"><span class="req-icon">◷</span><b>New leave request</b><small>Choose dates and submit your reason to the warden.</small></button><button class="request-card" onclick="openModal('feedback')"><span class="req-icon">♡</span><b>Send feedback</b><small>Share your experience and help improve hostel services.</small></button></div><div class="grid-2" style="margin-top:16px"><div class="card"><div class="card-head"><h3>My complaints</h3></div>${cs.length?cs.map(c=>`<div class="notice"><div class="notice-top"><b>${esc(c.category)}</b><span class="pill ${statusClass(c.status)}">${c.status}</span></div><p>${esc(c.description)}</p><small>${fmtDate(c.createdAt)} · ${esc(c.priority)} priority</small></div>`).join(''):'<div class="empty">No complaints raised.</div>'}</div><div class="card"><div class="card-head"><h3>My leave requests</h3></div>${ls.map(l=>`<div class="notice"><div class="notice-top"><b>${fmtDate(l.fromDate)} → ${fmtDate(l.toDate)}</b><span class="pill ${statusClass(l.status)}">${l.status}</span></div><p>${esc(l.reason)}</p></div>`).join('')||'<div class="empty">No leave requests.</div>'}</div></div>`}
function renderMess(){const days=state.menu;$('#pageRoot').innerHTML=pageHead(state.role==='ADMIN'?'OPERATIONS':'DINING','Mess menu',state.role==='ADMIN'?'Update the weekly menu residents see.':'Plan your meals for the week.',state.role==='ADMIN'?'<button class="action primary" onclick="openModal(\'menu\')">+ Add day</button>':'')+`<div class="menu-grid">${days.map(m=>`<div class="meal"><div class="meal-icon">✦</div><b>${esc(m.dayOfWeek)}</b><small><strong>Breakfast:</strong> ${esc(m.breakfast||'—')}<br><strong>Lunch:</strong> ${esc(m.lunch||'—')}<br><strong>Snacks:</strong> ${esc(m.snacks||'—')}<br><strong>Dinner:</strong> ${esc(m.dinner||'—')}</small>${state.role==='ADMIN'?`<button class="action" style="margin-top:12px" onclick="openModal('menu',${m.id})">Edit</button>`:''}</div>`).join('')}</div>`}
function renderStudents(){let rows=state.students;$('#pageRoot').innerHTML=pageHead('RESIDENT MANAGEMENT','Students','Manage resident records, room assignments and fee status.',`<input id="studentSearch" class="input" placeholder="Search name, register or department"><button class="action primary" onclick="openModal('student')">+ Add student</button>`)+`<div class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>RESIDENT</th><th>REGISTER</th><th>DEPARTMENT</th><th>ROOM</th><th>FEES</th><th>ACTIONS</th></tr></thead><tbody id="studentRows">${studentRows(rows)}</tbody></table></div></div>`;$('#studentSearch').oninput=e=>$('#studentRows').innerHTML=studentRows(state.students.filter(s=>(s.name+s.registerNumber+s.department).toLowerCase().includes(e.target.value.toLowerCase())))}
function studentRows(rows){return rows.map(s=>`<tr><td><div class="student-cell"><div class="mini-avatar">${initials(s.name)}</div><div><b>${esc(s.name)}</b><small style="display:block;color:#9aa2b1;font-size:7px">${esc(s.email)}</small></div></div></td><td>${esc(s.registerNumber)}</td><td>${esc(s.department)} · ${esc(s.year)}</td><td>${esc(s.roomNumber||'Unallocated')}</td><td><span class="pill ${s.feeStatus==='PAID'?'green':'orange'}">${s.feeStatus}</span></td><td><button class="action" onclick="openModal('profile',${s.id})">Edit</button> <button class="action ${s.feeStatus==='PAID'?'danger':'success'}" onclick="toggleFee(${s.id},'${s.feeStatus}')">${s.feeStatus==='PAID'?'Mark due':'Mark paid'}</button></td></tr>`).join('')||'<tr><td colspan="6"><div class="empty">No students found.</div></td></tr>'}
function renderRooms(){const rooms=state.rooms;$('#pageRoot').innerHTML=pageHead('RESIDENTIAL INVENTORY','Rooms','See capacity, occupancy and room availability at a glance.',`<button class="action primary" onclick="openModal('room')">+ Add room</button>`)+`<div class="room-grid">${rooms.map(r=>{const pct=Math.min(100,Math.round(r.occupied/r.capacity*100));return `<div class="room-card"><div class="room-top"><div><div class="room-no">${esc(r.roomNumber)}</div><div class="room-meta">${esc(r.blockName)} · Floor ${esc(r.floor)} · ${esc(r.type)}</div></div><span class="pill ${r.status==='FULL'?'red':'green'}">${r.status}</span></div><div class="progress"><i style="width:${pct}%"></i></div><div class="room-foot"><span>${r.occupied} / ${r.capacity} occupied</span><b>${pct}%</b></div><div style="margin-top:10px"><button class="action" onclick="openAllocation(${r.id})">Manage beds</button></div></div>`}).join('')}</div>`}
function renderMovements(){const a=state.movements;$('#pageRoot').innerHTML=pageHead('SAFETY & GATE','Gate movement','Approve residents going out and record their return to hostel.',`<button class="action" onclick="refreshData()">↻ Refresh</button>`)+`<div class="stats">${stat('PENDING',a.filter(x=>x.status==='REQUESTED').length,'Awaiting approval','◷')}${stat('OUTSIDE',a.filter(x=>x.status==='OUT').length,'Currently out','↗')}${stat('CHECKED IN',a.filter(x=>x.status==='IN').length,'Completed returns','✓')}${stat('REJECTED',a.filter(x=>x.status==='REJECTED').length,'Denied requests','×')}</div><div class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>RESIDENT</th><th>REASON</th><th>REQUESTED</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody>${a.map(m=>`<tr><td><div class="student-cell"><div class="mini-avatar">${initials(m.studentName)}</div><span><b>${esc(m.studentName)}</b><small style="display:block;color:#9aa2b1;font-size:7px">${m.registerNumber} · ${m.roomNumber||'—'}</small></span></div></td><td>${esc(m.reason)}</td><td>${fmtDate(m.requestedAt)}<br><small>${fmtTime(m.requestedAt)}</small></td><td><span class="pill ${statusClass(m.status)}">${m.status}</span></td><td>${m.status==='REQUESTED'?`<button class="action success" onclick="approveMovement(${m.id})">Approve & OUT</button> <button class="action danger" onclick="rejectMovement(${m.id})">Reject</button>`:m.status==='OUT'?`<button class="action primary" onclick="checkInMovement(${m.id})">Mark IN</button>`:`<span style="font-size:8px;color:#9aa2b1">${m.inTime?'Returned '+fmtTime(m.inTime):'Completed'}</span>`}</td></tr>`).join('')||'<tr><td colspan="5"><div class="empty">No gate movements.</div></td></tr>'}</tbody></table></div></div>`}
function renderComplaints(){const a=state.complaints.slice().reverse();$('#pageRoot').innerHTML=pageHead('SERVICE DESK','Complaints','Triage resident issues, approve work and close resolved requests.',`<button class="action" onclick="refreshData()">↻ Refresh</button>`)+`<div class="stats">${stat('OPEN',a.filter(x=>x.status==='OPEN').length,'Waiting for review','!')}${stat('IN PROGRESS',a.filter(x=>x.status==='IN_PROGRESS').length,'Being handled','◷')}${stat('RESOLVED',a.filter(x=>x.status==='RESOLVED').length,'Closed issues','✓')}${stat('HIGH PRIORITY',a.filter(x=>x.priority==='HIGH'&&x.status!=='RESOLVED').length,'Needs attention','!')}</div><div class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>RESIDENT</th><th>CATEGORY</th><th>DESCRIPTION</th><th>PRIORITY</th><th>STATUS</th><th></th></tr></thead><tbody>${a.map(c=>`<tr><td>${esc(c.studentName)}</td><td>${esc(c.category)}</td><td style="max-width:280px">${esc(c.description)}</td><td><span class="pill ${c.priority==='HIGH'?'red':c.priority==='MEDIUM'?'orange':'blue'}">${c.priority}</span></td><td><span class="pill ${statusClass(c.status)}">${c.status}</span></td><td>${c.status==='OPEN'?`<button class="action success" onclick="approveComplaint(${c.id})">Approve</button>`:c.status==='IN_PROGRESS'?`<button class="action primary" onclick="resolveComplaint(${c.id})">Resolve</button>`:'—'}</td></tr>`).join('')||'<tr><td colspan="6"><div class="empty">No complaints.</div></td></tr>'}</tbody></table></div></div>`}
function renderLeaves(){const a=state.leaves.slice().reverse();$('#pageRoot').innerHTML=pageHead('APPROVALS','Leave requests','Review and approve resident leave applications.',`<button class="action" onclick="refreshData()">↻ Refresh</button>`)+`<div class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>RESIDENT</th><th>DATES</th><th>REASON</th><th>STATUS</th><th></th></tr></thead><tbody>${a.map(l=>`<tr><td><b>${esc(l.studentName)}</b><small style="display:block;color:#9aa2b1;font-size:7px">${esc(l.registerNumber)}</small></td><td>${fmtDate(l.fromDate)} → ${fmtDate(l.toDate)}</td><td>${esc(l.reason)}</td><td><span class="pill ${statusClass(l.status)}">${l.status}</span></td><td>${l.status==='PENDING'?`<button class="action success" onclick="setLeave(${l.id},'APPROVED')">Approve</button> <button class="action danger" onclick="setLeave(${l.id},'REJECTED')">Reject</button>`:'—'}</td></tr>`).join('')||'<tr><td colspan="5"><div class="empty">No leave requests.</div></td></tr>'}</tbody></table></div></div>`}
function renderFees(){const pending=state.students.filter(s=>s.feeStatus!=='PAID');$('#pageRoot').innerHTML=pageHead('FINANCE','Fees & payments','Track resident fee status and record payments.',`<button class="action primary" onclick="openModal('payment')">+ Record payment</button>`)+`<div class="stats">${stat('PENDING',pending.length,'Residents with dues','₹')}${stat('PAID',state.students.length-pending.length,'Fees cleared','✓')}${stat('PAYMENTS',state.payments.length,'Receipts issued','▤')}${stat('COLLECTED','₹'+Math.round(state.payments.reduce((a,p)=>a+p.amount,0)).toLocaleString('en-IN'),'Recorded payments','₹')}</div><div class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>RESIDENT</th><th>REGISTER</th><th>FEE STATUS</th><th>LAST PAYMENT</th><th></th></tr></thead><tbody>${state.students.map(s=>{const p=state.payments.filter(x=>x.registerNumber===s.registerNumber).sort((a,b)=>new Date(b.paidAt)-new Date(a.paidAt))[0];return `<tr><td>${esc(s.name)}</td><td>${s.registerNumber}</td><td><span class="pill ${s.feeStatus==='PAID'?'green':'orange'}">${s.feeStatus}</span></td><td>${p?p.receiptNumber:'No receipt'}</td><td><button class="action ${s.feeStatus==='PAID'?'danger':'success'}" onclick="toggleFee(${s.id},'${s.feeStatus}')">${s.feeStatus==='PAID'?'Mark due':'Mark paid'}</button></td></tr>`}).join('')}</tbody></table></div></div>`}
function renderVisitors(){const a=state.visitors.slice().reverse();$('#pageRoot').innerHTML=pageHead('FRONT DESK','Visitors','Register, check in and check out hostel visitors.',`<button class="action primary" onclick="openModal('visitor')">+ Visitor pass</button>`)+`<div class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>VISITOR</th><th>RESIDENT</th><th>DATE</th><th>STATUS</th><th></th></tr></thead><tbody>${a.map(v=>`<tr><td><b>${esc(v.visitorName)}</b><small style="display:block;color:#9aa2b1;font-size:7px">${esc(v.relation||'Guest')} · ${esc(v.phone)}</small></td><td>${esc(v.studentName)}</td><td>${fmtDate(v.visitDate)}</td><td><span class="pill ${v.status==='CHECKED_IN'?'orange':v.status==='CHECKED_OUT'?'green':'blue'}">${v.status}</span></td><td>${v.status==='EXPECTED'?`<button class="action success" onclick="visitorAction(${v.id},'in')">Check in</button>`:v.status==='CHECKED_IN'?`<button class="action primary" onclick="visitorAction(${v.id},'out')">Check out</button>`:'—'}</td></tr>`).join('')||'<tr><td colspan="5"><div class="empty">No visitor passes.</div></td></tr>'}</tbody></table></div></div>`}
function renderNotices(){const a=state.notices.slice().reverse();$('#pageRoot').innerHTML=pageHead('COMMUNICATION','Notices & events','Publish important hostel updates, events and resident information.',`<button class="action primary" onclick="openModal('notice')">+ Publish notice</button>`)+`<div class="grid-2"><div class="card">${a.map(n=>noticeHtml(n,true)).join('')||'<div class="empty">No notices.</div>'}</div><div class="card"><div class="card-head"><h3>Publishing tips</h3></div><div class="timeline"><div class="timeline-item"><i></i><div><b>Keep titles short</b><small>Residents should understand the purpose at a glance.</small></div></div><div class="timeline-item"><i></i><div><b>Choose the right audience</b><small>Use All, Students, Staff or Event.</small></div></div><div class="timeline-item"><i></i><div><b>Use announcements for time-sensitive updates</b><small>Gate timings, inspections and events work well here.</small></div></div></div></div></div>`}
function renderFeedback(){const a=state.role==='ADMIN'?state.feedback.slice().reverse():state.feedback.filter(f=>f.registerNumber===state.user.registerNumber).slice().reverse();$('#pageRoot').innerHTML=pageHead('VOICE OF RESIDENTS','Feedback','Use resident feedback to continuously improve hostel services.',state.role==='STUDENT'?'<button class="action primary" onclick="openModal(\'feedback\')">+ Send feedback</button>':'')+`<div class="grid-2"><div class="card">${a.map(f=>`<div class="notice"><div class="notice-top"><b>${esc(f.category)} · ${esc(f.studentName)}</b><span class="feedback-stars">${'★'.repeat(f.rating)}${'☆'.repeat(5-f.rating)}</span></div><p>${esc(f.message)}</p><small>${fmtDate(f.createdAt)}</small></div>`).join('')||'<div class="empty">No feedback yet.</div>'}</div><div class="card"><div class="card-head"><h3>Service pulse</h3><span>${state.feedback.length} responses</span></div><div class="hero" style="min-height:240px;padding:22px"><div><span class="eyebrow">RESIDENT VOICE</span><h1 style="font-size:25px">Small feedback.<br>Better hostel.</h1><p>Feedback helps the hostel team identify what is working and where residents need support.</p></div></div></div></div>`}
function renderSettings(){const admin=state.role==='ADMIN';$('#pageRoot').innerHTML=pageHead('PREFERENCES','Settings','Personalise your HostelHub workspace.')+`<div class="grid-2"><div class="card"><div class="card-head"><h3>Appearance</h3></div><div class="info-box" style="margin-bottom:10px"><span>THEME</span><b>${state.dark?'Dark':'Light'} mode</b><button class="action" style="margin-top:9px" onclick="toggleTheme()">Switch theme</button></div><div class="info-box"><span>ROLE</span><b>${admin?'Administrator / Warden':'Student / Resident'}</b></div></div><div class="card"><div class="card-head"><h3>Security</h3></div><div class="timeline"><div class="timeline-item"><i></i><div><b>Server-validated login</b><small>Your role and credentials are checked by Spring Boot.</small></div></div><div class="timeline-item"><i></i><div><b>Session stored locally</b><small>Use Log out whenever you finish on a shared computer.</small></div></div><div class="timeline-item"><i></i><div><b>Operational audit trail</b><small>Movement, complaints and approvals generate live events.</small></div></div></div></div></div>`}
function noticeHtml(n,admin=false){return `<div class="notice"><div class="notice-top"><b>${esc(n.title)}</b><span>${esc(n.audience||'All')}</span></div><p>${esc(n.message)}</p><small>${fmtDate(n.createdAt)} ${admin?' · Published':''}</small></div>`}
function movementCard(m){return `<div class="notice"><div class="notice-top"><b>${esc(m.reason)}</b><span class="pill ${statusClass(m.status)}">${m.status}</span></div><p>${fmtDate(m.requestedAt)} · ${m.outTime?'Out '+fmtTime(m.outTime):''} ${m.inTime?' · In '+fmtTime(m.inTime):''}</p></div>`}
function movementRows(a){return a.map(m=>`<div class="notice"><div class="notice-top"><b>${esc(m.studentName)}</b><span class="pill orange">REQUESTED</span></div><p>${esc(m.reason)} · ${m.roomNumber||'—'}</p><button class="action success" onclick="approveMovement(${m.id})">Approve & OUT</button></div>`).join('')||'<div class="empty">No pending gate requests.</div>'}
function recentActivity(){return [...state.complaints.map(x=>({text:`Complaint · ${x.category} · ${x.studentName}`,time:fmtTime(x.createdAt)})),...state.movements.map(x=>({text:`Gate · ${x.studentName} · ${x.status}`,time:fmtTime(x.requestedAt)})),...state.feedback.map(x=>({text:`Feedback · ${x.studentName} · ${x.rating}/5`,time:fmtTime(x.createdAt)}))].sort(()=>Math.random()-.5).slice(0,5)}
function statusClass(s){return ({OPEN:'red',IN_PROGRESS:'orange',RESOLVED:'green',PENDING:'orange',APPROVED:'green',REJECTED:'red',REQUESTED:'orange',OUT:'purple',IN:'green',EXPECTED:'blue',CHECKED_IN:'orange',CHECKED_OUT:'green'}[s]||'blue')}
function go(p){state.page=p;buildNav();renderPage();window.scrollTo({top:0,behavior:'smooth'})}
async function refreshData(silent=false){if(state.refreshing)return;state.refreshing=true;try{await loadAll();buildNav();renderPage();if(!silent)toast('Workspace refreshed')}catch(e){if(!silent)toast(e.message,'err')}finally{state.refreshing=false}}
function startRealtime(){if(state.stream)state.stream.close();try{state.stream=new EventSource('/api/events/stream');const names=['complaint','gate','leave','payment','notice','student','room','visitor','feedback'];names.forEach(name=>state.stream.addEventListener(name,e=>{toast(e.data);refreshData(true)}));state.stream.onerror=()=>{};}catch(e){}}
async function approveComplaint(id){try{const c=state.complaints.find(x=>x.id===id);await api(`/api/complaints/${id}/${c.status==='OPEN'?'approve':'resolve'}`,{method:'PATCH'});await refreshData();toast(c.status==='OPEN'?'Complaint approved':'Complaint resolved')}catch(e){toast(e.message,'err')}}
async function resolveComplaint(id){try{await api(`/api/complaints/${id}/resolve`,{method:'PATCH'});await refreshData();toast('Complaint marked resolved')}catch(e){toast(e.message,'err')}}
async function approveMovement(id){try{await api(`/api/movements/${id}/approve?by=${encodeURIComponent(state.user.displayName||'Warden')}`,{method:'PATCH'});await refreshData();toast('Resident approved and marked OUT')}catch(e){toast(e.message,'err')}}
async function rejectMovement(id){try{await api(`/api/movements/${id}/reject?by=${encodeURIComponent(state.user.displayName||'Warden')}`,{method:'PATCH'});await refreshData();toast('Exit request rejected')}catch(e){toast(e.message,'err')}}
async function checkInMovement(id){try{await api(`/api/movements/${id}/check-in`,{method:'PATCH'});await refreshData();toast('Resident checked IN')}catch(e){toast(e.message,'err')}}
async function checkInMine(id){await checkInMovement(id);go('passport')}
async function setLeave(id,status){try{await api(`/api/leaves/${id}/${status}`,{method:'PATCH'});await refreshData();toast(`Leave ${status.toLowerCase()}`)}catch(e){toast(e.message,'err')}}
async function toggleFee(id,current){try{await api(`/api/students/${id}/fee?status=${current==='PAID'?'PENDING':'PAID'}`,{method:'PATCH'});await refreshData();toast('Fee status updated')}catch(e){toast(e.message,'err')}}
async function visitorAction(id,which){try{await api(`/api/visitors/${id}/check-${which}`,{method:'PATCH'});await refreshData();toast(`Visitor checked ${which}`)}catch(e){toast(e.message,'err')}}
function openAllocation(id){const r=state.rooms.find(x=>x.id===id);const available=state.students.filter(s=>!s.roomId);openCustom('Manage room '+r.roomNumber,`<div class="form-grid"><div class="form-field full"><label>ALLOCATE A RESIDENT</label><select class="select" id="allocStudent">${available.map(s=>`<option value="${s.id}">${esc(s.name)} · ${s.registerNumber}</option>`).join('')}</select></div></div><div class="modal-actions"><button class="action" data-close>Cancel</button><button class="action primary" onclick="allocateRoom(${r.id})">Allocate bed</button></div>`)}
async function allocateRoom(id){const sid=$('#allocStudent')?.value;if(!sid)return;try{await api(`/api/rooms/${id}/allocate/${sid}`,{method:'POST'});closeModal();await refreshData();toast('Resident allocated to room')}catch(e){toast(e.message,'err')}}
function openCustom(title,body){$('#modalRoot').innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="modal-head"><div><h3>${title}</h3><p>HostelHub workspace</p></div><button class="modal-close" data-close>×</button></div>${body}</div></div>`;$$('[data-close]').forEach(x=>x.onclick=closeModal)}
function openModal(type,id=null){const st=currentStudent()||{};const selected=state.students.find(x=>x.id===id)||st;let title='',body='';
if(type==='complaint') {title='Raise a complaint';body=`<div class="form-grid"><div class="form-field"><label>CATEGORY</label><select id="fCategory" class="select"><option>Maintenance</option><option>Internet</option><option>Electrical</option><option>Mess</option><option>Safety</option><option>Feedback</option></select></div><div class="form-field"><label>PRIORITY</label><select id="fPriority" class="select"><option>LOW</option><option selected>MEDIUM</option><option>HIGH</option></select></div><div class="form-field full"><label>DESCRIPTION</label><textarea id="fDescription" class="textarea" rows="4" placeholder="Tell the hostel team what happened..."></textarea></div></div><div class="modal-actions"><button class="action" data-close>Cancel</button><button class="action primary" onclick="submitComplaint()">Submit complaint</button></div>`}
if(type==='leave'){title='Apply for leave';body=`<div class="form-grid"><div class="form-field"><label>FROM</label><input id="lFrom" type="date" class="input"></div><div class="form-field"><label>TO</label><input id="lTo" type="date" class="input"></div><div class="form-field full"><label>REASON</label><textarea id="lReason" class="textarea" rows="4" placeholder="Reason for leave"></textarea></div></div><div class="modal-actions"><button class="action" data-close>Cancel</button><button class="action primary" onclick="submitLeave()">Send for approval</button></div>`}
if(type==='movement'){title='Request permission to go out';body=`<div class="form-grid"><div class="form-field full"><label>REASON</label><textarea id="mReason" class="textarea" rows="4" placeholder="Shopping, appointment, family visit..."></textarea></div></div><div class="modal-actions"><button class="action" data-close>Cancel</button><button class="action primary" onclick="submitMovement()">Request approval</button></div>`}
if(type==='feedback'){title='Share feedback';body=`<div class="form-grid"><div class="form-field"><label>CATEGORY</label><select id="fbCategory" class="select"><option>Hostel</option><option>Mess</option><option>Cleanliness</option><option>Security</option><option>Facilities</option></select></div><div class="form-field"><label>RATING</label><select id="fbRating" class="select"><option value="5">5 · Excellent</option><option value="4">4 · Good</option><option value="3">3 · Okay</option><option value="2">2 · Needs work</option><option value="1">1 · Poor</option></select></div><div class="form-field full"><label>MESSAGE</label><textarea id="fbMessage" class="textarea" rows="4" placeholder="What can we improve?"></textarea></div></div><div class="modal-actions"><button class="action" data-close>Cancel</button><button class="action primary" onclick="submitFeedback()">Send feedback</button></div>`}
if(type==='student'){title='Add resident';body=`<div class="form-grid"><div class="form-field"><label>FULL NAME</label><input id="sn" class="input"></div><div class="form-field"><label>REGISTER NUMBER</label><input id="sr" class="input"></div><div class="form-field"><label>EMAIL</label><input id="se" class="input"></div><div class="form-field"><label>DEPARTMENT</label><input id="sd" class="input" value="CSE"></div><div class="form-field"><label>YEAR</label><input id="sy" class="input" value="IV"></div></div><div class="modal-actions"><button class="action" data-close>Cancel</button><button class="action primary" onclick="submitStudent()">Create resident</button></div>`}
if(type==='profile'){title='Edit resident details';body=`<div class="form-grid"><div class="form-field"><label>FULL NAME</label><input id="pn" class="input" value="${esc(selected.name)}"></div><div class="form-field"><label>EMAIL</label><input id="pe" class="input" value="${esc(selected.email)}"></div><div class="form-field"><label>DEPARTMENT</label><input id="pd" class="input" value="${esc(selected.department)}"></div><div class="form-field"><label>YEAR</label><input id="py" class="input" value="${esc(selected.year)}"></div></div><div class="modal-actions"><button class="action" data-close>Cancel</button><button class="action primary" onclick="saveProfile(${selected.id})">Save changes</button></div>`}
if(type==='payment'){title='Record payment';body=`<div class="form-grid"><div class="form-field full"><label>RESIDENT</label><select id="payStudent" class="select">${state.students.map(s=>`<option value="${s.registerNumber}" data-name="${esc(s.name)}">${esc(s.name)} · ${s.registerNumber}</option>`).join('')}</select></div><div class="form-field"><label>AMOUNT (₹)</label><input id="payAmount" type="number" class="input" value="25000"></div><div class="form-field"><label>FEE TYPE</label><select id="payType" class="select"><option>Hostel Fee</option><option>Mess Fee</option><option>Other</option></select></div></div><div class="modal-actions"><button class="action" data-close>Cancel</button><button class="action primary" onclick="submitPayment()">Record payment</button></div>`}
if(type==='visitor'){title='Create visitor pass';body=`<div class="form-grid"><div class="form-field"><label>RESIDENT</label><select id="vStudent" class="select">${state.students.map(s=>`<option>${esc(s.name)}</option>`).join('')}</select></div><div class="form-field"><label>VISITOR NAME</label><input id="vName" class="input"></div><div class="form-field"><label>RELATION</label><input id="vRel" class="input" placeholder="Parent / Sibling"></div><div class="form-field"><label>PHONE</label><input id="vPhone" class="input"></div></div><div class="modal-actions"><button class="action" data-close>Cancel</button><button class="action primary" onclick="submitVisitor()">Create pass</button></div>`}
if(type==='notice'){title='Publish notice';body=`<div class="form-grid"><div class="form-field full"><label>TITLE</label><input id="nt" class="input"></div><div class="form-field"><label>AUDIENCE</label><select id="na" class="select"><option>All Students</option><option>Students</option><option>Event</option><option>Staff</option></select></div><div class="form-field full"><label>MESSAGE</label><textarea id="nm" class="textarea" rows="4"></textarea></div></div><div class="modal-actions"><button class="action" data-close>Cancel</button><button class="action primary" onclick="submitNotice()">Publish</button></div>`}
if(type==='menu'){const m=state.menu.find(x=>x.id===id);title=m?'Edit menu day':'Add menu day';body=`<div class="form-grid"><div class="form-field"><label>DAY</label><input id="md" class="input" value="${m?esc(m.dayOfWeek):''}" ${m?'disabled':''}></div><div class="form-field"><label>BREAKFAST</label><input id="mb" class="input" value="${m?esc(m.breakfast):''}"></div><div class="form-field"><label>LUNCH</label><input id="ml" class="input" value="${m?esc(m.lunch):''}"></div><div class="form-field"><label>SNACKS</label><input id="ms" class="input" value="${m?esc(m.snacks):''}"></div><div class="form-field full"><label>DINNER</label><input id="mdi" class="input" value="${m?esc(m.dinner):''}"></div></div><div class="modal-actions"><button class="action" data-close>Cancel</button><button class="action primary" onclick="saveMenu(${m?m.id:'null'})">Save menu</button></div>`}
if(type==='room'){title='Add room';body=`<div class="form-grid"><div class="form-field"><label>ROOM NUMBER</label><input id="rn" class="input"></div><div class="form-field"><label>CAPACITY</label><input id="rc" type="number" class="input" value="4"></div><div class="form-field"><label>BLOCK</label><input id="rb" class="input" value="A Block"></div><div class="form-field"><label>FLOOR</label><input id="rf" class="input" value="1"></div><div class="form-field full"><label>TYPE</label><input id="rt" class="input" value="4 Sharing"></div></div><div class="modal-actions"><button class="action" data-close>Cancel</button><button class="action primary" onclick="submitRoom()">Create room</button></div>`}
openCustom(title,body)}
async function submitComplaint(){const s=currentStudent();try{await api('/api/complaints',{method:'POST',body:JSON.stringify({studentName:s.name,category:$('#fCategory').value,priority:$('#fPriority').value,description:$('#fDescription').value})});closeModal();await refreshData();toast('Complaint submitted')}catch(e){toast(e.message,'err')}}
async function submitLeave(){const s=currentStudent();try{await api('/api/leaves',{method:'POST',body:JSON.stringify({studentName:s.name,registerNumber:s.registerNumber,fromDate:$('#lFrom').value,toDate:$('#lTo').value,reason:$('#lReason').value})});closeModal();await refreshData();toast('Leave request sent')}catch(e){toast(e.message,'err')}}
async function submitMovement(){const s=currentStudent();try{await api('/api/movements',{method:'POST',body:JSON.stringify({studentName:s.name,registerNumber:s.registerNumber,roomNumber:s.roomNumber,reason:$('#mReason').value})});closeModal();await refreshData();toast('Gate request sent for approval')}catch(e){toast(e.message,'err')}}
async function submitFeedback(){const s=currentStudent();try{await api('/api/feedback',{method:'POST',body:JSON.stringify({studentName:s.name,registerNumber:s.registerNumber,rating:Number($('#fbRating').value),category:$('#fbCategory').value,message:$('#fbMessage').value})});closeModal();await refreshData();toast('Thanks for your feedback')}catch(e){toast(e.message,'err')}}
async function submitStudent(){try{const s=await api('/api/students',{method:'POST',body:JSON.stringify({name:$('#sn').value,registerNumber:$('#sr').value,email:$('#se').value,department:$('#sd').value,year:$('#sy').value})});closeModal();await refreshData();toast(`${s.name} added`)}catch(e){toast(e.message,'err')}}
async function saveProfile(id){try{await api(`/api/students/${id}`,{method:'PATCH',body:JSON.stringify({name:$('#pn').value,email:$('#pe').value,department:$('#pd').value,year:$('#py').value})});closeModal();await refreshData();toast('Resident details updated')}catch(e){toast(e.message,'err')}}
async function submitPayment(){const o=$('#payStudent').selectedOptions[0];try{await api('/api/payments',{method:'POST',body:JSON.stringify({studentName:o.dataset.name,registerNumber:o.value,amount:Number($('#payAmount').value),feeType:$('#payType').value})});closeModal();await refreshData();toast('Payment recorded')}catch(e){toast(e.message,'err')}}
async function submitVisitor(){try{await api('/api/visitors',{method:'POST',body:JSON.stringify({studentName:$('#vStudent').value,visitorName:$('#vName').value,relation:$('#vRel').value,phone:$('#vPhone').value})});closeModal();await refreshData();toast('Visitor pass created')}catch(e){toast(e.message,'err')}}
async function submitNotice(){try{await api('/api/notices',{method:'POST',body:JSON.stringify({title:$('#nt').value,message:$('#nm').value,audience:$('#na').value})});closeModal();await refreshData();toast('Notice published')}catch(e){toast(e.message,'err')}}
async function saveMenu(id){try{const x={dayOfWeek:$('#md').value,breakfast:$('#mb').value,lunch:$('#ml').value,snacks:$('#ms').value,dinner:$('#mdi').value};await api(id?`/api/mess/${id}`:'/api/mess',{method:id?'PUT':'POST',body:JSON.stringify(x)});closeModal();await refreshData();toast('Mess menu saved')}catch(e){toast(e.message,'err')}}
async function submitRoom(){try{await api('/api/rooms',{method:'POST',body:JSON.stringify({roomNumber:$('#rn').value,capacity:Number($('#rc').value),blockName:$('#rb').value,floor:$('#rf').value,type:$('#rt').value})});closeModal();await refreshData();toast('Room added')}catch(e){toast(e.message,'err')}}
function closeModal(){$('#modalRoot').innerHTML=''}
function toggleTheme(){state.dark=!state.dark;document.body.classList.toggle('dark',state.dark);localStorage.setItem('hostelhubTheme',state.dark?'dark':'light')}
function logout(){if(state.stream)state.stream.close();localStorage.removeItem('hostelhubUser');state.user=null;state.role=null;$('#app').classList.add('hidden');$('#loginView').classList.remove('hidden');$('#loginPassword').value='';toast('Signed out')}
async function boot(){state.dark=localStorage.getItem('hostelhubTheme')==='dark';document.body.classList.toggle('dark',state.dark);const saved=localStorage.getItem('hostelhubUser');if(saved){try{state.user=JSON.parse(saved);state.role=state.user.role;await loadAll();showApp();return}catch{localStorage.removeItem('hostelhubUser')}}}
$$('.role-btn').forEach(b=>b.onclick=()=>{$$('.role-btn').forEach(x=>x.classList.remove('active'));b.classList.add('active');state.role=b.dataset.role;$('#identityLabel').firstChild.textContent=state.role==='ADMIN'?'Username':'Register number';$('#loginIdentity').placeholder=state.role==='ADMIN'?'e.g. admin':'e.g. CSE001';$('#demoHint').innerHTML=state.role==='ADMIN'?'Demo · admin / admin123':'Demo · CSE001 / student123'});
$('#loginForm').onsubmit=async e=>{e.preventDefault();try{const u=await api('/api/auth/login',{method:'POST',body:JSON.stringify({role:state.role||'STUDENT',identity:$('#loginIdentity').value,password:$('#loginPassword').value})});setUser(u);state.role=u.role;await loadAll();showApp();toast(`Welcome, ${u.displayName}`)}catch(err){toast(err.message,'err')}};
$('#logoutBtn').onclick=logout;$('#topLogoutBtn').onclick=logout;$('#menuToggle').onclick=()=>{$('#sidebar').classList.toggle('open');$('#mobileBackdrop').classList.toggle('show')};$('#mobileBackdrop').onclick=()=>{$('#sidebar').classList.remove('open');$('#mobileBackdrop').classList.remove('show')};$('#themeBtn').onclick=toggleTheme;$('#bellBtn').onclick=()=>toast(state.role==='ADMIN'?`${countFor('complaints')||0} complaints · ${countFor('movement')||0} gate requests need attention`:'Your hostel notifications are up to date');
$('#userMini').onclick=()=>go(state.role==='ADMIN'?'settings':'profile');
window.go=go;window.openModal=openModal;window.refreshData=refreshData;window.approveComplaint=approveComplaint;window.resolveComplaint=resolveComplaint;window.approveMovement=approveMovement;window.rejectMovement=rejectMovement;window.checkInMovement=checkInMovement;window.checkInMine=checkInMine;window.setLeave=setLeave;window.toggleFee=toggleFee;window.visitorAction=visitorAction;window.openAllocation=openAllocation;window.allocateRoom=allocateRoom;window.toggleTheme=toggleTheme;window.closeModal=closeModal;
state.role='STUDENT';boot();
